#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    // trie: children, number of strings ending here, longest string in the subtree
    vector<array<int, 2>> ch(1, {-1, -1});
    vector<int> terminal(1, 0), maxLen(1, 0);
    for (int i = 0; i < n; i++) {
        string s;
        cin >> s;
        int node = 0;
        for (char c : s) {
            int bit = c - '0';
            if (ch[node][bit] < 0) {
                ch[node][bit] = ch.size();
                ch.push_back({-1, -1});
                terminal.push_back(0);
                maxLen.push_back(0);
            }
            node = ch[node][bit];
        }
        terminal[node]++;
        maxLen[node] = s.size();
    }
    int m = ch.size();
    // children have larger indices, so reverse index order is a postorder
    for (int v = m - 1; v >= 0; v--)
        for (int c : ch[v]) if (c >= 0) maxLen[v] = max(maxLen[v], maxLen[c]);
    vector<int> depth(m, 0);
    for (int v = 0; v < m; v++)
        for (int c : ch[v]) if (c >= 0) depth[c] = depth[v] + 1;
    long long answer = 0;
    for (int v = 0; v < m; v++) {
        // groups: strings ending here, strings into child 0, strings into child 1
        vector<int> groups;
        if (terminal[v]) groups.push_back(depth[v]);
        for (int c : ch[v]) if (c >= 0) groups.push_back(maxLen[c]);
        if (groups.size() >= 2) {
            sort(groups.rbegin(), groups.rend());
            answer = max(answer, (long long)groups[0] + groups[1] - 2LL * depth[v]);
        }
    }
    cout << answer << "\n";
}

import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf = new byte[1 << 16];
    static int len = 0, ptr = 0;
    static InputStream is = System.in;

    static int readByte() throws IOException {
        if (ptr == len) { len = is.read(buf, 0, buf.length); ptr = 0; if (len <= 0) return -1; }
        return buf[ptr++];
    }

    static String next() throws IOException {
        int c = readByte();
        while (c != -1 && c <= ' ') c = readByte();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') { sb.append((char) c); c = readByte(); }
        return sb.toString();
    }

    static long nextLong() throws IOException {
        int c = readByte();
        while (c != '-' && (c < '0' || c > '9')) c = readByte();
        boolean neg = c == '-';
        if (neg) c = readByte();
        long r = 0;
        while (c >= '0' && c <= '9') { r = r * 10 + (c - '0'); c = readByte(); }
        return neg ? -r : r;
    }

    public static void main(String[] args) throws IOException {
        int n = (int) nextLong();
        int cap = 200005;
        // trie: children, number of strings ending here, longest string in the subtree
        int[] c0 = new int[cap], c1 = new int[cap], terminal = new int[cap], maxLen = new int[cap];
        c0[0] = c1[0] = -1;
        int m = 1;
        for (int i = 0; i < n; i++) {
            String s = next();
            int node = 0;
            for (int k = 0; k < s.length(); k++) {
                int[] ch = s.charAt(k) == '0' ? c0 : c1;
                if (ch[node] < 0) {
                    if (m == c0.length) {
                        int nc = c0.length * 2;
                        c0 = Arrays.copyOf(c0, nc); c1 = Arrays.copyOf(c1, nc);
                        terminal = Arrays.copyOf(terminal, nc); maxLen = Arrays.copyOf(maxLen, nc);
                        ch = s.charAt(k) == '0' ? c0 : c1;
                    }
                    c0[m] = c1[m] = -1;
                    ch[node] = m++;
                }
                node = ch[node];
            }
            terminal[node]++;
            maxLen[node] = s.length();
        }
        // children have larger indices, so reverse index order is a postorder
        for (int v = m - 1; v >= 0; v--) {
            if (c0[v] >= 0) maxLen[v] = Math.max(maxLen[v], maxLen[c0[v]]);
            if (c1[v] >= 0) maxLen[v] = Math.max(maxLen[v], maxLen[c1[v]]);
        }
        int[] depth = new int[m];
        for (int v = 0; v < m; v++) {
            if (c0[v] >= 0) depth[c0[v]] = depth[v] + 1;
            if (c1[v] >= 0) depth[c1[v]] = depth[v] + 1;
        }
        long answer = 0;
        int[] groups = new int[3];
        for (int v = 0; v < m; v++) {
            // groups: strings ending here, strings into child 0, strings into child 1
            int g = 0;
            if (terminal[v] > 0) groups[g++] = depth[v];
            if (c0[v] >= 0) groups[g++] = maxLen[c0[v]];
            if (c1[v] >= 0) groups[g++] = maxLen[c1[v]];
            if (g >= 2) {
                Arrays.sort(groups, 0, g);
                answer = Math.max(answer, (long) groups[g - 1] + groups[g - 2] - 2L * depth[v]);
            }
        }
        System.out.println(answer);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
	"sort"
	"strconv"
)

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Buffer(make([]byte, 1<<20), 1<<26)
	sc.Split(bufio.ScanWords)
	sc.Scan()
	n, _ := strconv.Atoi(sc.Text())
	// trie: children, number of strings ending here, longest string in the subtree
	ch := [][2]int{{-1, -1}}
	terminal := []int{0}
	maxLen := []int{0}
	for i := 0; i < n; i++ {
		sc.Scan()
		s := sc.Text()
		node := 0
		for k := 0; k < len(s); k++ {
			bit := int(s[k] - '0')
			if ch[node][bit] < 0 {
				ch[node][bit] = len(ch)
				ch = append(ch, [2]int{-1, -1})
				terminal = append(terminal, 0)
				maxLen = append(maxLen, 0)
			}
			node = ch[node][bit]
		}
		terminal[node]++
		maxLen[node] = len(s)
	}
	m := len(ch)
	// children have larger indices, so reverse index order is a postorder
	for v := m - 1; v >= 0; v-- {
		for _, c := range ch[v] {
			if c >= 0 {
				maxLen[v] = max(maxLen[v], maxLen[c])
			}
		}
	}
	depth := make([]int, m)
	for v := 0; v < m; v++ {
		for _, c := range ch[v] {
			if c >= 0 {
				depth[c] = depth[v] + 1
			}
		}
	}
	answer := 0
	for v := 0; v < m; v++ {
		// groups: strings ending here, strings into child 0, strings into child 1
		var groups []int
		if terminal[v] > 0 {
			groups = append(groups, depth[v])
		}
		for _, c := range ch[v] {
			if c >= 0 {
				groups = append(groups, maxLen[c])
			}
		}
		if len(groups) >= 2 {
			sort.Sort(sort.Reverse(sort.IntSlice(groups)))
			answer = max(answer, groups[0]+groups[1]-2*depth[v])
		}
	}
	fmt.Println(answer)
}
